        "function initChart(){\n  const c=document.getElementById('chart-box');\n  if(!c||typeof LightweightCharts==='undefined') return;\n  try{\n    chart=LightweightCharts.createChart(c,{\n      autoSize:true,\n      layout:{background:{color:'#040408'},textColor:'#666'},\n      grid:{vertLines:{color:'#0f0f18'},horzLines:{color:'#0f0f18'}},\n      rightPriceScale:{borderColor:'#1e1e2e'},\n      timeScale:{borderColor:'#1e1e2e',timeVisible:true},\n    });\n    candleSeries=chart.addCandlestickSeries({\n      upColor:'#00cc44',downColor:'#cc2200',\n      borderUpColor:'#00cc44',borderDownColor:'#cc2200',\n      wickUpColor:'#00cc44',wickDownColor:'#cc2200',\n    });\n    ema9Series=chart.addLineSeries({color:'#00bfff',lineWidth:1,priceLineVisible:false,lastValueVisible:false,title:'EMA9'});\n    ema21Series=chart.addLineSeries({color:'#ff9900',lineWidth:1,priceLineVisible:false,lastValueVisible:false,title:'EMA21'});\n    vwapSeries=chart.addLineSeries({color:'#c084fc',lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false,title:'VWAP'});\n    window.addEventListener('resize',()=>{if(chart)chart.applyOptions({width:c.clientWidth});});\n  }catch(e){console.warn('Chart init failed:',e);}\n}\n\n",
