        '/* ── Pivot Points (S1-S3 green / R1-R3 red) with proximity highlighting ── */\nfunction setPivotBasis(basis){\n  pivotBasis=basis;\n  document.querySelectorAll(\'.pivot-btn\').forEach(b=>{\n    const on=b.dataset.basis===basis;\n    b.style.background=on?\'#003311\':\'#0a0a14\';\n    b.style.borderColor=on?\'#00ff88\':\'#333\';\n    b.style.color=on?\'#00ff88\':\'#aaa\';\n  });\n  fetchChart();\n}\n\nfunction updatePivotLevels(symbol, currentPrice){\n  fetch(`/pivot_points?symbol=${symbol}&type=${pivotBasis}`).then(r=>r.json()).then(pv=>{\n    const confEl=document.getElementById(\'sr-confidence-val\');\n    const panel=document.getElementById(\'key-levels-panel\');\n    if(!pv.available){\n      if(confEl){ confEl.textContent=\'No data\'; confEl.style.color=\'var(--grey)\'; }\n      if(panel) panel.innerHTML=\'<div style="color:var(--grey);font-size:9px">No pivot data available</div>\';\n      return;\n    }\n    const levels=[\n      {label:\'R3\',price:pv.r3,color:\'var(--red)\'},\n      {label:\'R2\',price:pv.r2,color:\'var(--red)\'},\n      {label:\'R1\',price:pv.r1,color:\'var(--red)\'},\n      {label:\'P\', price:pv.pivot,color:\'var(--gold)\'},\n      {label:\'S1\',price:pv.s1,color:\'var(--green)\'},\n      {label:\'S2\',price:pv.s2,color:\'var(--green)\'},\n      {label:\'S3\',price:pv.s3,color:\'var(--green)\'},\n    ];\n    let minDistPct=Infinity;\n    const rows=levels.filter(lv=>lv.price).map(lv=>{\n      const distPct=currentPrice?Math.abs(currentPrice-lv.price)/currentPrice*100:100;\n      const near=distPct<=0.3;\n      if(distPct<minDistPct) minDistPct=distPct;\n      return `<div style="display:flex;justify-content:space-between;padding:2px 0;font-size:9px;${near?\'background:rgba(255,215,0,0.12);border-radius:2px;padding-left:3px\':\'\'}">\n        <span style="color:${lv.color};font-weight:${near?\'bold\':\'normal\'}">${near?\'🔥 \':\'\'}${lv.label}</span>\n        <span style="color:${near?\'var(--white)\':\'var(--grey)\'};font-weight:${near?\'bold\':\'normal\'}">${fmt6(lv.price)}</span>\n      </div>`;\n    }).join(\'\');\n    if(panel) panel.innerHTML=rows;\n    if(confEl){\n      const score=Math.max(0, Math.round(100-Math.min(minDistPct,5)*20));\n      confEl.textContent=score+\'% (\'+(minDistPct<0.3?\'price near a key level\':\'no level nearby\')+\')\';\n      confEl.style.color=score>=70?\'var(--green)\':score>=40?\'var(--gold)\':\'var(--grey)\';\n    }\n  }).catch(()=>{\n    const confEl=document.getElementById(\'sr-confidence-val\');\n    if(confEl){ confEl.textContent=\'Fetch failed\'; confEl.style.color=\'var(--grey)\'; }\n  });\n}\n\n/* ── Multi-Timeframe RSI strip ── */\nfunction toggleMultiTfStrip(){\n  const strip=document.getElementById(\'multi-tf-strip\');\n  const btn=document.getElementById(\'tf-all-btn\');\n  if(!strip) return;\n  const show=strip.style.display===\'none\';\n  strip.style.display=show?\'block\':\'none\';\n  if(btn){ btn.style.background=show?\'#a855f7\':\'#1a0a2e\'; btn.style.color=show?\'#fff\':\'#c084fc\'; }\n  if(show) fetchMultiTfRsi();\n}\n\nfunction fetchMultiTfRsi(){\n  const symbol=(document.getElementById(\'coin-inp\')?.value||\'BTCUSDT\').toUpperCase().replace(/[^A-Z0-9]/g,\'\');\n  const sym=symbol.includes(\'USDT\')?symbol:symbol+\'USDT\';\n  fetch(`/rsi_multi_tf?symbol=${sym}`).then(r=>r.json()).then(d=>{\n    const rsi=d.rsi||{};\n    document.querySelectorAll(\'[data-tf-rsi]\').forEach(el=>{\n      const tf=el.dataset.tfRsi;\n      const v=rsi[tf];\n      if(v===null||v===undefined){ el.textContent=\'—\'; el.style.color=\'var(--grey)\'; return; }\n      el.textContent=v;\n      el.style.color=v>=70?\'var(--red)\':v<=30?\'var(--green)\':\'var(--gold)\';\n    });\n  }).catch(()=>{});\n}\n\n/* ── Live candle-close countdown (chart corner, tracks currentTF) ── */\nconst TF_SECONDS={\'1m\':60,\'5m\':300,\'15m\':900,\'1h\':3600,\'4h\':14400,\'8h\':28800,\'1d\':86400};\nfunction startChartCandleCountdown(){\n  function tick(){\n    const el=document.getElementById(\'candle-countdown\');\n    if(!el) return;\n    const dur=TF_SECONDS[currentTF]||900;\n',
        "/* ══════════════════════════════════════════════════════════════\n   FULL-SCREEN SCALPING CHART — single chart engine, replaces the\n   old Sniper embedded chart and the Command-tab chart widgets.\n   Live updates via a direct browser->Binance WebSocket connection\n   (bypasses the server entirely, so it also sidesteps any\n   server-hosting-region restriction that can block server-side\n   Binance WebSocket connections).\n   ══════════════════════════════════════════════════════════════ */\nwindow._scalpState = {\n  symbol: 'BTCUSDT', tf: '1m',\n  chart: null, candleSeries: null,\n  bbUpperSeries: null, bbLowerSeries: null, vwapSeries: null, ema9Series: null, ema21Series: null,\n  rsiSeries: null, volumeSeries: null,\n  candles: [], ws: null,\n};\nconst SCALP_TF_SECONDS={'1m':60,'5m':300,'15m':900,'1h':3600,'4h':14400,'8h':28800,'1d':86400};\n\nfunction openScalpingChart(){\n  const overlay=document.getElementById('scalping-overlay');\n  if(!overlay) return;\n  overlay.style.display='flex';\n  const sniperInp=document.getElementById('coin-inp');\n  let sym='BTCUSDT';\n  if(sniperInp && sniperInp.value){\n    const s=sniperInp.value.toUpperCase().replace(/[^A-Z0-9]/g,'');\n    if(s) sym=s.includes('USDT')?s:s+'USDT';\n  }\n  window._scalpState.symbol=sym;\n  const inp=document.getElementById('scalp-symbol-inp');\n  if(inp) inp.value=sym.replace('USDT','');\n  scalpLoad();\n  scalpStartCountdown();\n}\n\nfunction closeScalpingChart(){\n  const overlay=document.getElementById('scalping-overlay');\n  if(overlay) overlay.style.display='none';\n  if(window._scalpState.ws){ try{ window._scalpState.ws.close(); }catch(e){} window._scalpState.ws=null; }\n  if(window._scalpCountdownTimer){ clearInterval(window._scalpCountdownTimer); window._scalpCountdownTimer=null; }\n}\n\nfunction scalpChangeSymbol(){\n  const inp=document.getElementById('scalp-symbol-inp');\n  if(!inp) return;\n  const s=inp.value.toUpperCase().replace(/[^A-Z0-9]/g,'');\n  if(!s) return;\n  window._scalpState.symbol=s.includes('USDT')?s:s+'USDT';\n  scalpLoad();\n}\n\nfunction scalpSetTf(tf){\n  window._scalpState.tf=tf;\n  document.querySelectorAll('.scalp-tf-btn').forEach(b=>{\n    const on=b.dataset.tf===tf;\n    b.style.background=on?'#003311':'#0a0a14';\n    b.style.borderColor=on?'#00ff88':'#333';\n    b.style.color=on?'#00ff88':'#aaa';\n  });\n  scalpLoad();\n}\n\nfunction scalpInitChart(){\n  const box=document.getElementById('scalp-main-chart');\n  const st=document.getElementById('scalp-status');\n  if(!box) return;\n  if(typeof LightweightCharts==='undefined'){ if(st) st.textContent='Chart library not loaded'; return; }\n  try{\n    const w=box.clientWidth||window.innerWidth||360;\n    const h=box.clientHeight||(window.innerHeight-160)||400;\n    const c=LightweightCharts.createChart(box,{\n      width:w, height:h, autoSize:true,\n      layout:{background:{color:'#040408'},textColor:'#666'},\n      grid:{vertLines:{color:'#0f0f18'},horzLines:{color:'#0f0f18'}},\n      rightPriceScale:{borderColor:'#1e1e2e', scaleMargins:{top:0.05,bottom:0.45}},\n      timeScale:{borderColor:'#1e1e2e',timeVisible:true},\n    });\n    const candleSeries=c.addCandlestickSeries({\n      upColor:'#00cc44',downColor:'#cc2200',borderUpColor:'#00cc44',borderDownColor:'#cc2200',\n      wickUpColor:'#00cc44',wickDownColor:'#cc2200',\n    });\n    const bbUpperSeries=c.addLineSeries({color:'rgba(150,150,170,0.6)',lineWidth:1,priceLineVisible:false,lastValueVisible:false});\n    const bbLowerSeries=c.addLineSeries({color:'rgba(150,150,170,0.6)',lineWidth:1,priceLineVisible:false,lastValueVisible:false});\n    const vwapSeries=c.addLineSeries({color:'#c084fc',lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false});\n    const ema9Series=c.addLineSeries({color:'#00bfff',lineWidth:1,priceLineVisible:false,lastValueVisible:false});\n    const ema21Series=c.addLineSeries({color:'#ff9900',lineWidth:1,priceLineVisible:false,lastValueVisible:false});\n\n    const rsiSeries=c.addLineSeries({color:'#c084fc', lineWidth:1, priceScaleId:'rsi', priceLineVisible:false, lastValueVisible:true});\n    c.priceScale('rsi').applyOptions({scaleMargins:{top:0.58,bottom:0.20}, borderColor:'#1e1e2e'});\n\n    const volumeSeries=c.addHistogramSeries({priceScaleId:'volume', priceLineVisible:false, lastValueVisible:false});\n    c.priceScale('volume').applyOptions({scaleMargins:{top:0.85,bottom:0.0}, borderColor:'#1e1e2e'});\n\n    const s=window._scalpState;\n    s.chart=c; s.candleSeries=candleSeries; s.bbUpperSeries=bbUpperSeries; s.bbLowerSeries=bbLowerSeries;\n    s.vwapSeries=vwapSeries; s.ema9Series=ema9Series; s.ema21Series=ema21Series;\n    s.rsiSeries=rsiSeries; s.volumeSeries=volumeSeries;\n\n    window.addEventListener('resize',()=>{ if(s.chart && box) s.chart.resize(box.clientWidth, box.clientHeight); });\n  }catch(e){\n    console.warn('Scalping chart init failed:', e);\n    if(st) st.textContent='Chart init error: '+e.message;\n  }\n}\n\nfunction scalpCalcBollinger(candles, period, mult){\n  period=period||20; mult=mult||2;\n  const upper=[], lower=[];\n  for(let i=period-1;i<candles.length;i++){\n    const win=candles.slice(i-period+1, i+1);\n    const mean=win.reduce((s,c)=>s+c.close,0)/period;\n    const variance=win.reduce((s,c)=>s+Math.pow(c.close-mean,2),0)/period;\n    const sd=Math.sqrt(variance);\n    upper.push({time:candles[i].time, value:mean+mult*sd});\n    lower.push({time:candles[i].time, value:mean-mult*sd});\n  }\n  return {upper, lower};\n}\n\nfunction scalpCalcVWAP(candles){\n  let cumPV=0, cumVol=0;\n  return candles.map(c=>{\n    const typical=(c.high+c.low+c.close)/3;\n    const vol=c.volume||0;\n    cumPV+=typical*vol; cumVol+=vol;\n    return {time:c.time, value:cumVol?cumPV/cumVol:typical};\n  });\n}\n\nfunction scalpCalcRSISeries(candles, period){\n  period=period||14;\n  if(candles.length<period+1) return [];\n  const out=[];\n  let gains=0, losses=0;\n  for(let i=1;i<=period;i++){\n    const d=candles[i].close-candles[i-1].close;\n    if(d>0) gains+=d; else losses-=d;\n  }\n  let avgGain=gains/period, avgLoss=losses/period;\n  out.push({time:candles[period].time, value: avgLoss===0?100:100-(100/(1+avgGain/avgLoss))});\n  for(let i=period+1;i<candles.length;i++){\n    const d=candles[i].close-candles[i-1].close;\n    const g=Math.max(d,0), l=Math.max(-d,0);\n    avgGain=(avgGain*(period-1)+g)/period;\n    avgLoss=(avgLoss*(period-1)+l)/period;\n    out.push({time:candles[i].time, value: avgLoss===0?100:100-(100/(1+avgGain/avgLoss))});\n  }\n  return out;\n}\n\n/* ── Candle pattern detection ── */\nfunction scalpDetectPattern(candles){\n  if(candles.length<3) return {name:'Insufficient data', dir:'neutral'};\n  const c0=candles[candles.length-3], c1=candles[candles.length-2], c2=candles[candles.length-1];\n  const body=c=>Math.abs(c.close-c.open);\n  const range=c=>(c.high-c.low)||1e-9;\n  const upperWick=c=>c.high-Math.max(c.open,c.close);\n  const lowerWick=c=>Math.min(c.open,c.close)-c.low;\n  const isBull=c=>c.close>c.open;\n  const isBear=c=>c.close<c.open;\n\n  if(body(c2)/range(c2) < 0.1) return {name:'Doji', dir:'neutral'};\n  if(isBear(c1) && isBull(c2) && c2.open<=c1.close && c2.close>=c1.open) return {name:'Bullish Engulfing', dir:'bullish'};\n  if(isBull(c1) && isBear(c2) && c2.open>=c1.close && c2.close<=c1.open) return {name:'Bearish Engulfing', dir:'bearish'};\n  if(lowerWick(c2) > body(c2)*2 && upperWick(c2) < body(c2)*0.5 && isBull(c2)) return {name:'Hammer', dir:'bullish'};\n  if(upperWick(c2) > body(c2)*2 && lowerWick(c2) < body(c2)*0.5 && isBear(c2)) return {name:'Shooting Star', dir:'bearish'};\n  if(isBear(c0) && body(c1)/range(c1) < 0.3 && isBull(c2) && c2.close > (c0.open+c0.close)/2) return {name:'Morning Star', dir:'bullish'};\n  if(isBull(c0) && body(c1)/range(c1) < 0.3 && isBear(c2) && c2.close < (c0.open+c0.close)/2) return {name:'Evening Star', dir:'bearish'};\n  return {name: isBull(c2)?'Bullish candle':'Bearish candle', dir: isBull(c2)?'bullish':'bearish'};\n}\n\nfunction scalpPredictNext(pattern, rsi, price, bbUpper, bbLower){\n  const bullishPatterns=['Bullish Engulfing','Hammer','Morning Star'];\n  const bearishPatterns=['Bearish Engulfing','Shooting Star','Evening Star'];\n  if(price<=bbLower && rsi<30 && bullishPatterns.includes(pattern)) return {text:'Bullish Bounce', color:'var(--green)'};\n  if(price>=bbUpper && rsi>70 && bearishPatterns.includes(pattern)) return {text:'Bearish Reversal', color:'var(--red)'};\n  return {text:'Neutral', color:'var(--grey)'};\n}\n\nfunction scalpLoad(){\n  const st=document.getElementById('scalp-status');\n  const titleEl=document.getElementById('scalp-title');\n  const sym=window._scalpState.symbol, tf=window._scalpState.tf;\n  if(titleEl) titleEl.textContent='Scalping Chart — '+sym.replace('USDT','/USDT');\n  if(st) st.textContent='Loading '+sym+' '+tf+'...';\n  if(!window._scalpState.chart) scalpInitChart();\n\n  fetch(`/chart_data?symbol=${sym}&interval=${tf}&limit=100`).then(r=>r.json()).then(d=>{\n    if(!d.candles || !d.candles.length){ if(st) st.textContent='No data for '+sym; return; }\n    const candles=d.candles.map(c=>({\n      time:c.time, open:parseFloat(c.open), high:parseFloat(c.high), low:parseFloat(c.low), close:parseFloat(c.close),\n      volume:parseFloat(c.volume||0),\n    }));\n    window._scalpState.candles=candles;\n    scalpRenderAll(candles);\n    if(st) st.textContent=candles.length+' candles ('+sym+' '+tf+') — live via WebSocket';\n    scalpConnectWebSocket(sym, tf);\n  }).catch(()=>{ if(st) st.textContent='Chart fetch failed'; });\n}\n\nfunction scalpRenderAll(candles){\n  const s=window._scalpState;\n  if(!s.candleSeries) return;\n  try{\n    s.candleSeries.setData(candles.map(c=>({time:c.time,open:c.open,high:c.high,low:c.low,close:c.close})));\n    const bb=scalpCalcBollinger(candles,20,2);\n    if(s.bbUpperSeries) s.bbUpperSeries.setData(bb.upper);\n    if(s.bbLowerSeries) s.bbLowerSeries.setData(bb.lower);\n    if(s.vwapSeries) s.vwapSeries.setData(scalpCalcVWAP(candles));\n    if(s.ema9Series) s.ema9Series.setData(calcEMASeries(candles,9));\n    if(s.ema21Series) s.ema21Series.setData(calcEMASeries(candles,21));\n    const rsiData=scalpCalcRSISeries(candles,14);\n    if(s.rsiSeries) s.rsiSeries.setData(rsiData);\n    if(s.volumeSeries) s.volumeSeries.setData(candles.map(c=>({time:c.time,value:c.volume,color:c.close>=c.open?'rgba(0,204,68,0.6)':'rgba(204,34,0,0.6)'})));\n\n    const pattern=scalpDetectPattern(candles);\n    const nameEl=document.getElementById('scalp-pattern-name');\n    if(nameEl){\n      nameEl.textContent=pattern.name;\n      nameEl.style.color=pattern.dir==='bullish'?'var(--green)':pattern.dir==='bearish'?'var(--red)':'var(--grey)';\n    }\n    const lastRsi=rsiData.length?rsiData[rsiData.length-1].value:50;\n    const lastPrice=candles[candles.length-1].close;\n    const lastBBUpper=bb.upper.length?bb.upper[bb.upper.length-1].value:lastPrice;\n    const lastBBLower=bb.lower.length?bb.lower[bb.lower.length-1].value:lastPrice;\n    const pred=scalpPredictNext(pattern.name, lastRsi, lastPrice, lastBBUpper, lastBBLower);\n    const predEl=document.getElementById('scalp-next-prediction');\n    if(predEl){ predEl.textContent='Next: '+pred.text; predEl.style.color=pred.color; }\n\n    scalpCheckVolumeSpike(candles);\n  }catch(e){\n    console.warn('scalpRenderAll failed:', e);\n    const st=document.getElementById('scalp-status');\n    if(st) st.textContent='Render error: '+e.message;\n  }\n}\n\nfunction scalpCheckVolumeSpike(candles){\n  const alertEl=document.getElementById('scalp-volume-alert');\n  if(!alertEl || candles.length<21){ if(alertEl) alertEl.style.display='none'; return; }\n  const recent=candles.slice(-21,-1);\n  const avgVol=recent.reduce((s,c)=>s+c.volume,0)/recent.length;\n  const last=candles[candles.length-1];\n  if(avgVol<=0){ alertEl.style.display='none'; return; }\n  const ratio=last.volume/avgVol;\n  if(ratio>=2){\n    const bullish=last.close>=last.open;\n    alertEl.style.display='block';\n    alertEl.textContent='⚡ Alert: Volume Spike ('+ratio.toFixed(1)+'x Avg)';\n    alertEl.style.background=bullish?'rgba(0,204,68,0.18)':'rgba(204,34,0,0.18)';\n    alertEl.style.color=bullish?'var(--green)':'var(--red)';\n  }else{\n    alertEl.style.display='none';\n  }\n}\n\n/* ── Live updates via direct browser -> Binance WebSocket ── */\nfunction scalpConnectWebSocket(symbol, tf){\n  const s=window._scalpState;\n  if(s.ws){ try{ s.ws.close(); }catch(e){} s.ws=null; }\n  const streamSymbol=symbol.toLowerCase();\n  const url=`wss://stream.binance.com:9443/ws/${streamSymbol}@kline_${tf}`;\n  try{\n    const ws=new WebSocket(url);\n    s.ws=ws;\n    ws.onmessage=(ev)=>{\n      if(window._scalpState.symbol!==symbol || window._scalpState.tf!==tf) return;\n      try{\n        const msg=JSON.parse(ev.data);\n        const k=msg.k;\n        if(!k) return;\n        const candle={time:Math.floor(k.t/1000), open:parseFloat(k.o), high:parseFloat(k.h), low:parseFloat(k.l), close:parseFloat(k.c), volume:parseFloat(k.v)};\n        const arr=window._scalpState.candles;\n        if(arr.length && arr[arr.length-1].time===candle.time) arr[arr.length-1]=candle;\n        else{ arr.push(candle); if(arr.length>300) arr.shift(); }\n        scalpRenderAll(arr);\n      }catch(e){}\n    };\n    ws.onerror=()=>{\n      const st=document.getElementById('scalp-status');\n      if(st) st.textContent='Live feed unavailable — showing last fetched data';\n    };\n  }catch(e){\n    console.warn('Scalping WS connect failed:', e);\n  }\n}\n\nfunction scalpStartCountdown(){\n  if(window._scalpCountdownTimer) clearInterval(window._scalpCountdownTimer);\n  function tick(){\n    const el=document.getElementById('scalp-candle-countdown');\n    if(!el) return;\n    const dur=SCALP_TF_SECONDS[window._scalpState.tf]||60;\n",
