        "}\n\nfunction setTimeframe(tf){\n  currentTF=tf;\n  document.querySelectorAll('.tf-btn').forEach(b=>{\n    const active=b.getAttribute('data-tf')===tf;\n    b.style.background=active?'#003311':'#0a0a14';\n    b.style.borderColor=active?'#00ff88':'#333';\n    b.style.color=active?'#00ff88':'#aaa';\n  });\n  fetchChart();\n",
